# Staff training desk

Private application for an internal training coordinator and employee portal. Target runtime is Node 22 ESM. There are no runtime dependencies. Use `npm run typecheck`, `npm run build`, and `npm test` after installing the declared development tooling.

`model.ts` owns directory email normalization and domain error codes. `store.ts` owns per-desk mutable session state. `desk.ts` is the trusted in-process application API. `portal.ts` contains the current JSON submission caller and attendance export caller. Seeds come from the coordinator's typed configuration, not arbitrary JSON; their business constraints are checked at desk construction. Submission JSON is untrusted and is validated at the portal boundary. Unknown extra JSON fields are ignored today.

Employees enroll in a session with a fixed positive seat capacity. Emails are trimmed and lowercased, then checked for a basic email shape. Duplicate enrollment is rejected. Cancellation removes an existing enrollment. Attendance contains confirmed employees in enrollment order.

Full sessions accept waitlist opt-ins in join order. Admissions start open and can be paused with `setAdmissions(sessionId, open)`; rosters expose `admissionsOpen`. While paused, enrollment fails with ADMISSIONS_CLOSED before email or duplicate validation. Cancellations remain available without promoting waiters. Reopening fills every available seat from the waiting list in FIFO order, before new arrivals can take seats. Repeating the current admissions state is harmless.

Domain failures throw `DeskError` with stable `code` values: INVALID_SESSION, DUPLICATE_SESSION, NOT_FOUND, INVALID_EMAIL, ALREADY_ENROLLED, FULL, NOT_ENROLLED, ADMISSIONS_CLOSED. Portal submission translates domain errors into failure replies; malformed JSON shapes produce BAD_REQUEST. Unexpected programming errors propagate. For desk operations, session existence is checked before email validation. Failed operations do not change state. Each desk owns its data; seeds, returned enrollments, rosters and attendance arrays may be mutated by callers without altering stored data.

The desk and portal exports are used only by this application and its tests; there are no external package consumers. Tests execute built JavaScript from dist. Keep the attendance export and portal submission consistent with the application rules.
{
  "name": "staff-training-desk",
  "private": true,
  "type": "module",
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build": "tsc",
    "test": "npm run build && node --test tests/*.test.mjs"
  },
  "devDependencies": {
    "typescript": "5.9.3"
  }
}
export interface SessionSeed {
  id: string;
  title: string;
  capacity: number;
}

export interface Enrollment {
  email: string;
  status: 'confirmed' | 'waitlisted';
}

export interface Roster {
  id: string;
  title: string;
  capacity: number;
  admissionsOpen: boolean;
  enrollments: Enrollment[];
}

export class DeskError extends Error {
  constructor(public readonly code: string, message: string) {
    super(message);
    this.name = 'DeskError';
  }
}

// Email is the company directory's stable identifier for this application.
export function canonicalEmail(value: string): string {
  const email = value.trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new DeskError('INVALID_EMAIL', 'A directory email is required');
  }
  return email;
}
import { DeskError, type Enrollment, type SessionSeed } from './model.js';

export interface SessionState extends SessionSeed {
  admissionsOpen: boolean;
  enrollments: Enrollment[];
}

// Owned by one desk instance. Never exposed directly to callers.
export class SessionStore {
  private readonly sessions = new Map<string, SessionState>();

  constructor(seeds: readonly SessionSeed[]) {
    for (const seed of seeds) {
      if (!seed.id || !seed.title || !Number.isInteger(seed.capacity) || seed.capacity < 1) {
        throw new DeskError('INVALID_SESSION', 'Sessions need an id, title and positive capacity');
      }
      if (this.sessions.has(seed.id)) {
        throw new DeskError('DUPLICATE_SESSION', 'Session ids must be unique');
      }
      this.sessions.set(seed.id, { ...seed, admissionsOpen: true, enrollments: [] });
    }
  }

  get(id: string): SessionState {
    const session = this.sessions.get(id);
    if (!session) throw new DeskError('NOT_FOUND', 'Unknown training session');
    return session;
  }
}
import { canonicalEmail, DeskError, type Enrollment, type Roster, type SessionSeed } from './model.js';
import { SessionStore, type SessionState } from './store.js';

export class TrainingDesk {
  private readonly store: SessionStore;

  constructor(seeds: readonly SessionSeed[]) {
    this.store = new SessionStore(seeds);
  }

  enroll(sessionId: string, rawEmail: string, options?: { waitlist: boolean }): Enrollment {
    const session = this.store.get(sessionId);
    if (!session.admissionsOpen) {
      throw new DeskError('ADMISSIONS_CLOSED', 'Session admissions are closed');
    }
    const email = canonicalEmail(rawEmail);
    if (session.enrollments.some(entry => entry.email === email)) {
      throw new DeskError('ALREADY_ENROLLED', 'Employee already enrolled');
    }
    const full = session.enrollments.some(entry => entry.status === 'waitlisted') ||
      session.enrollments.filter(entry => entry.status === 'confirmed').length >= session.capacity;
    if (full && !options?.waitlist) {
      throw new DeskError('FULL', 'Session is full');
    }
    const entry: Enrollment = { email, status: full ? 'waitlisted' : 'confirmed' };
    session.enrollments.push(entry);
    return { ...entry };
  }

  cancel(sessionId: string, rawEmail: string): void {
    const session = this.store.get(sessionId);
    const email = canonicalEmail(rawEmail);
    const index = session.enrollments.findIndex(entry => entry.email === email);
    if (index < 0) throw new DeskError('NOT_ENROLLED', 'Employee is not enrolled');
    session.enrollments.splice(index, 1);
    this.fillAvailableSeats(session);
  }

  setAdmissions(sessionId: string, open: boolean): void {
    const session = this.store.get(sessionId);
    session.admissionsOpen = open;
    this.fillAvailableSeats(session);
  }

  private fillAvailableSeats(session: SessionState): void {
    if (!session.admissionsOpen) return;
    let available = session.capacity -
      session.enrollments.filter(entry => entry.status === 'confirmed').length;
    for (const entry of session.enrollments) {
      if (available <= 0) break;
      if (entry.status === 'waitlisted') {
        entry.status = 'confirmed';
        available--;
      }
    }
  }

  roster(sessionId: string): Roster {
    const session = this.store.get(sessionId);
    return {
      id: session.id,
      title: session.title,
      capacity: session.capacity,
      admissionsOpen: session.admissionsOpen,
      enrollments: session.enrollments.map(entry => ({ ...entry })),
    };
  }
}
import { TrainingDesk } from './desk.js';
import { DeskError } from './model.js';

export type PortalReply =
  | { ok: true; status: string }
  | { ok: false; code: string };

// The HTTP adapter passes decoded JSON here; this is a real untrusted boundary.
export function submitEnrollment(desk: TrainingDesk, body: unknown): PortalReply {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, code: 'BAD_REQUEST' };
  }
  const input = body as Record<string, unknown>;
  if (typeof input.sessionId !== 'string' || typeof input.email !== 'string') {
    return { ok: false, code: 'BAD_REQUEST' };
  }
  if ('waitlist' in input && typeof input.waitlist !== 'boolean') {
    return { ok: false, code: 'BAD_REQUEST' };
  }
  try {
    const enrollment = desk.enroll(input.sessionId, input.email,
      typeof input.waitlist === 'boolean' ? { waitlist: input.waitlist } : undefined);
    return { ok: true, status: enrollment.status };
  } catch (error) {
    if (error instanceof DeskError) return { ok: false, code: error.code };
    throw error;
  }
}

// Used by the coordinator's daily attendance export.
export function attendanceEmails(desk: TrainingDesk, sessionId: string): string[] {
  return desk.roster(sessionId).enrollments
    .filter(entry => entry.status === 'confirmed')
    .map(entry => entry.email);
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { TrainingDesk } from '../dist/desk.js';
import { submitEnrollment, attendanceEmails } from '../dist/portal.js';
const make = () => new TrainingDesk([{ id: 's', title: 'First aid', capacity: 1 }]);
test('portal validates unknown data and normalizes directory identity', () => {
  const desk = make();
  assert.deepEqual(submitEnrollment(desk, null), { ok: false, code: 'BAD_REQUEST' });
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: ' A@EXAMPLE.COM ' }), { ok: true, status: 'confirmed' });
  assert.deepEqual(attendanceEmails(desk, 's'), ['a@example.com']);
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: 'a@example.com' }), { ok: false, code: 'ALREADY_ENROLLED' });
});
test('capacity and cancellation preserve atomic failures', () => {
  const desk = make();
  desk.enroll('s', 'a@example.com');
  assert.throws(() => desk.enroll('s', 'b@example.com'), { code: 'FULL' });
  assert.throws(() => desk.cancel('s', 'b@example.com'), { code: 'NOT_ENROLLED' });
  assert.equal(desk.roster('s').enrollments.length, 1);
  desk.cancel('s', ' A@example.com ');
  assert.equal(desk.enroll('s', 'b@example.com').status, 'confirmed');
});
test('snapshots and seeds have independent ownership', () => {
  const seeds = [{ id: 's', title: 'First aid', capacity: 1 }];
  const desk = new TrainingDesk(seeds);
  seeds[0].capacity = 9;
  const entry = desk.enroll('s', 'a@example.com');
  entry.email = 'changed@example.com';
  const roster = desk.roster('s');
  roster.enrollments[0].email = 'changed@example.com';
  roster.enrollments.length = 0;
  assert.equal(desk.roster('s').capacity, 1);
  assert.deepEqual(attendanceEmails(desk, 's'), ['a@example.com']);
});
test('configuration and domain errors', () => {
  assert.throws(() => new TrainingDesk([{ id: 's', title: 'x', capacity: 0 }]), { code: 'INVALID_SESSION' });
  const desk = make();
  assert.throws(() => desk.enroll('missing', 'bad'), { code: 'NOT_FOUND' });
  assert.throws(() => desk.enroll('s', 'bad'), { code: 'INVALID_EMAIL' });
  assert.deepEqual(desk.roster('s').enrollments, []);
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { TrainingDesk } from '../dist/desk.js';
import { submitEnrollment, attendanceEmails } from '../dist/portal.js';

const make = () => new TrainingDesk([{ id: 's', title: 'First aid', capacity: 1 }]);

test('opt-in confirms free seats and queues full sessions in join order', () => {
  const desk = make();
  assert.equal(desk.enroll('s', ' A@EXAMPLE.COM ', { waitlist: true }).status, 'confirmed');
  assert.throws(() => desk.enroll('s', 'b@example.com'), { code: 'FULL' });
  assert.throws(() => desk.enroll('s', 'b@example.com', { waitlist: false }), { code: 'FULL' });
  assert.deepEqual(desk.enroll('s', ' B@EXAMPLE.COM ', { waitlist: true }), {
    email: 'b@example.com', status: 'waitlisted',
  });
  desk.enroll('s', 'c@example.com', { waitlist: true });
  for (const email of [' A@example.com ', ' B@example.com ']) {
    assert.throws(() => desk.enroll('s', email, { waitlist: true }), { code: 'ALREADY_ENROLLED' });
    assert.throws(() => desk.enroll('s', email), { code: 'ALREADY_ENROLLED' });
  }
  assert.deepEqual(desk.roster('s').enrollments.map(e => e.status), ['confirmed', 'waitlisted', 'waitlisted']);
  assert.deepEqual(attendanceEmails(desk, 's'), ['a@example.com']);
  desk.cancel('s', ' A@example.com ');
  assert.deepEqual(desk.roster('s').enrollments, [
    { email: 'b@example.com', status: 'confirmed' },
    { email: 'c@example.com', status: 'waitlisted' },
  ]);
  assert.deepEqual(attendanceEmails(desk, 's'), ['b@example.com']);
  desk.cancel('s', 'b@example.com');
  assert.deepEqual(attendanceEmails(desk, 's'), ['c@example.com']);
});

test('cancelling a waiting employee removes them and rejoining goes to the end', () => {
  const desk = make();
  desk.enroll('s', 'a@example.com');
  desk.enroll('s', 'b@example.com', { waitlist: true });
  desk.enroll('s', 'c@example.com', { waitlist: true });
  desk.cancel('s', ' B@EXAMPLE.COM ');
  assert.deepEqual(attendanceEmails(desk, 's'), ['a@example.com']);
  desk.enroll('s', 'b@example.com', { waitlist: true });
  desk.cancel('s', 'a@example.com');
  assert.deepEqual(desk.roster('s').enrollments, [
    { email: 'c@example.com', status: 'confirmed' },
    { email: 'b@example.com', status: 'waitlisted' },
  ]);
});

test('portal validates optional waitlist before mutation and returns actual status', () => {
  const desk = make();
  const input = { sessionId: 's', email: 'a@example.com' };
  for (const waitlist of [undefined, null, 0, 1, 'true', [], {}]) {
    assert.deepEqual(submitEnrollment(desk, { ...input, waitlist }), { ok: false, code: 'BAD_REQUEST' });
    assert.deepEqual(desk.roster('s').enrollments, []);
  }
  assert.deepEqual(submitEnrollment(desk, { ...input, waitlist: true, extra: 1 }), { ok: true, status: 'confirmed' });
  const waiting = { sessionId: 's', email: ' B@EXAMPLE.COM ' };
  assert.deepEqual(submitEnrollment(desk, { ...waiting, waitlist: false }), { ok: false, code: 'FULL' });
  assert.deepEqual(submitEnrollment(desk, { ...waiting, waitlist: true }), { ok: true, status: 'waitlisted' });
  assert.deepEqual(submitEnrollment(desk, waiting), { ok: false, code: 'ALREADY_ENROLLED' });
});

test('waitlist snapshots, failures and desk instances preserve ownership', () => {
  const desk = make();
  desk.enroll('s', 'a@example.com');
  const waiting = desk.enroll('s', 'b@example.com', { waitlist: true });
  const roster = desk.roster('s');
  waiting.status = 'confirmed';
  roster.enrollments[1].email = 'changed@example.com';
  roster.enrollments[1].status = 'confirmed';
  const before = desk.roster('s');
  assert.throws(() => desk.cancel('s', 'missing@example.com'), { code: 'NOT_ENROLLED' });
  assert.throws(() => desk.enroll('missing', 'bad', { waitlist: true }), { code: 'NOT_FOUND' });
  assert.throws(() => desk.enroll('s', 'bad', { waitlist: true }), { code: 'INVALID_EMAIL' });
  assert.deepEqual(desk.roster('s'), before);
  assert.deepEqual(make().roster('s').enrollments, []);
  desk.cancel('s', 'a@example.com');
  assert.deepEqual(attendanceEmails(desk, 's'), ['b@example.com']);
  assert.deepEqual(roster.enrollments.map(e => e.email), ['a@example.com', 'changed@example.com']);
});

test('multiple confirmed seats promote one waiter per cancellation', () => {
  const desk = new TrainingDesk([{ id: 's', title: 'First aid', capacity: 2 }]);
  for (const email of ['a@example.com', 'b@example.com', 'c@example.com', 'd@example.com']) {
    desk.enroll('s', email, { waitlist: true });
  }
  desk.cancel('s', 'b@example.com');
  assert.deepEqual(attendanceEmails(desk, 's'), ['a@example.com', 'c@example.com']);
  assert.equal(desk.roster('s').enrollments.at(-1).status, 'waitlisted');
  desk.cancel('s', 'a@example.com');
  assert.deepEqual(attendanceEmails(desk, 's'), ['c@example.com', 'd@example.com']);
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { TrainingDesk } from '../dist/desk.js';
import { submitEnrollment, attendanceEmails } from '../dist/portal.js';

const make = (capacity = 1) => new TrainingDesk([
  { id: 's', title: 'First aid', capacity },
  { id: 'other', title: 'Safety', capacity: 1 },
]);

test('admissions start open and closure takes precedence over email and duplicates', () => {
  const desk = make();
  assert.equal(desk.roster('s').admissionsOpen, true);
  desk.enroll('s', 'a@example.com');
  desk.enroll('s', 'b@example.com', { waitlist: true });
  desk.setAdmissions('s', false);
  const before = desk.roster('s');
  for (const email of ['bad', ' A@EXAMPLE.COM ', 'b@example.com', 'new@example.com']) {
    for (const options of [undefined, { waitlist: false }, { waitlist: true }]) {
      assert.throws(() => desk.enroll('s', email, options), { code: 'ADMISSIONS_CLOSED' });
    }
  }
  assert.deepEqual(desk.roster('s'), before);
  assert.throws(() => desk.enroll('missing', 'bad'), { code: 'NOT_FOUND' });
  assert.throws(() => desk.setAdmissions('missing', false), { code: 'NOT_FOUND' });
  assert.equal(desk.enroll('other', 'new@example.com').status, 'confirmed');
  assert.equal(make().roster('s').admissionsOpen, true);
});

test('paused cancellations retain FIFO and reopening fills every free seat', () => {
  const desk = make(2);
  for (const name of ['a', 'b', 'c', 'd', 'e', 'f']) {
    desk.enroll('s', `${name}@example.com`, { waitlist: true });
  }
  desk.setAdmissions('s', false);
  desk.setAdmissions('s', false);
  desk.cancel('s', ' A@EXAMPLE.COM ');
  desk.cancel('s', 'b@example.com');
  desk.cancel('s', ' D@EXAMPLE.COM ');
  assert.deepEqual(attendanceEmails(desk, 's'), []);
  assert.deepEqual(desk.roster('s').enrollments, [
    { email: 'c@example.com', status: 'waitlisted' },
    { email: 'e@example.com', status: 'waitlisted' },
    { email: 'f@example.com', status: 'waitlisted' },
  ]);
  const paused = desk.roster('s');
  assert.throws(() => desk.cancel('s', 'bad'), { code: 'INVALID_EMAIL' });
  assert.throws(() => desk.cancel('s', 'missing@example.com'), { code: 'NOT_ENROLLED' });
  assert.deepEqual(desk.roster('s'), paused);
  desk.setAdmissions('s', true);
  assert.equal(desk.roster('s').admissionsOpen, true);
  assert.deepEqual(attendanceEmails(desk, 's'), ['c@example.com', 'e@example.com']);
  const reopened = desk.roster('s');
  desk.setAdmissions('s', true);
  assert.deepEqual(desk.roster('s'), reopened);
  assert.throws(() => desk.enroll('s', 'new@example.com'), { code: 'FULL' });
  assert.equal(desk.enroll('s', 'new@example.com', { waitlist: true }).status, 'waitlisted');
  desk.cancel('s', 'c@example.com');
  assert.deepEqual(attendanceEmails(desk, 's'), ['e@example.com', 'f@example.com']);
});

test('reopening with spare capacity admits new arrivals after existing waiters', () => {
  const desk = make(2);
  for (const name of ['a', 'b', 'c']) desk.enroll('s', `${name}@example.com`, { waitlist: true });
  desk.setAdmissions('s', false);
  desk.cancel('s', 'a@example.com');
  desk.cancel('s', 'b@example.com');
  desk.setAdmissions('s', true);
  assert.equal(desk.enroll('s', 'd@example.com').status, 'confirmed');
  assert.deepEqual(attendanceEmails(desk, 's'), ['c@example.com', 'd@example.com']);
  const snapshot = desk.roster('s');
  snapshot.admissionsOpen = false;
  assert.equal(desk.roster('s').admissionsOpen, true);
});

test('portal reports closure while preserving boundary validation and reopening behavior', () => {
  const desk = make();
  desk.setAdmissions('s', false);
  for (const waitlist of [true, false]) {
    assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: 'bad', waitlist }),
      { ok: false, code: 'ADMISSIONS_CLOSED' });
  }
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: 'a@example.com' }),
    { ok: false, code: 'ADMISSIONS_CLOSED' });
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: 'a@example.com', waitlist: 'true' }),
    { ok: false, code: 'BAD_REQUEST' });
  assert.deepEqual(desk.roster('s').enrollments, []);
  desk.setAdmissions('s', true);
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: ' A@EXAMPLE.COM ' }),
    { ok: true, status: 'confirmed' });
});

